// @pit: {"label": "Update README Pi version and CHANGELOG Unreleased entry"}
async ({ workspace: { search, edit } }, p: { cl: string }) => {
  const [r, c] = await Promise.all([
    search("currently Pi 1.5.2", { path: "README.md" }),
    search("## [Unreleased]", { path: "CHANGELOG.md" }),
  ]);
  const rm = r.matches[0], cm = c.matches[0];
  await edit("README.md", { revision: rm.revision, changes: [{ kind: "replace", start: rm.anchor, content: rm.text.replace("Pi 1.5.2", "Pi 1.6.0") }] });
  await edit("CHANGELOG.md", { revision: cm.revision, changes: [{ kind: "insertAfter", anchor: cm.anchor, content: p.cl }] });
  return "ok";
}
